"""Team entry point: python Infrastructure/run.py [suite/test path] [pytest options]."""
from pathlib import Path
import sys

INFRASTRUCTURE = Path(__file__).resolve().parent
ROOT = INFRASTRUCTURE.parent
# Keep generated bytecode out of the board folders.
sys.pycache_prefix = str(INFRASTRUCTURE / '.pycache')


if __name__ == '__main__':
    from backend.authoring import check_suite_hooks
    try:
        check_suite_hooks(ROOT / 'Suites')
    except (ValueError, SyntaxError, OSError) as error:
        raise SystemExit(f'Suite authoring check failed: {error}')
    import pytest
    raise SystemExit(pytest.main(['-c', str(INFRASTRUCTURE/'pytest.ini'), '--rootdir', str(ROOT), *sys.argv[1:]]))
